const state={balance:1250,selected:{name:'Popular',coins:2300,price:19.99}};
const profiles={sofia:{name:'Sofía',handle:'@sofia.ai',bio:'Arte, lifestyle y pequeños instantes que hacen especial cada día. ✦'},valentina:{name:'Valentina',handle:'@valentina.ai',bio:'Fantasía, estilo y conversaciones que van más allá. Aquí todo es posible. 💜'},isabella:{name:'Isabella',handle:'@isabella.v',bio:'Una colección de viajes, secretos y momentos creados para mirar de cerca.'},emilia:{name:'Emilia',handle:'@emilia.afterdark',bio:'Música, noches largas y una historia distinta en cada canción.'}};
const views=[...document.querySelectorAll('.view')];
function money(n){return new Intl.NumberFormat('en-US').format(n)}
function showView(id){views.forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}
function updateBalance(){document.querySelector('#walletBalance').innerHTML=`${money(state.balance)} <small>VC</small>`;document.querySelector('#sideBalance').textContent=`${money(state.balance)} VC`}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.view)showView(el.dataset.view);if(el.dataset.profile){const p=profiles[el.dataset.profile];document.querySelector('#profileName').innerHTML=`${p.name} <span class="verified">✓</span>`;document.querySelector('#profileHandle').textContent=p.handle;document.querySelector('#profileBio').textContent=p.bio;showView('profile')}if(el.classList.contains('follow')){el.classList.toggle('following');el.textContent=el.classList.contains('following')?'Siguiendo':'Seguir';toast(el.classList.contains('following')?'Ahora sigues a esta creadora':'Dejaste de seguir a esta creadora')}if(el.classList.contains('chat-open'))showView('chat');if(el.dataset.unlock)unlock(+el.dataset.unlock);if(el.closest('#packages'))choosePackage(el);if(el.classList.contains('close')||e.target.classList.contains('scrim'))closeCheckout();if(el.classList.contains('next'))nextCheckout();if(el.classList.contains('pay'))pay();if(el.classList.contains('done')){closeCheckout();showView('wallet')}if(el.classList.contains('done-explore')){closeCheckout();showView('explore')}});
function choosePackage(el){state.selected={name:el.dataset.package[0].toUpperCase()+el.dataset.package.slice(1),coins:+el.dataset.coins,price:+el.dataset.price};['chosenName','receiptName'].forEach(id=>document.querySelector('#'+id).textContent=id==='receiptName'?`Paquete ${state.selected.name}`:state.selected.name);['chosenCoins','receiptCoins','successCoins'].forEach(id=>document.querySelector('#'+id).textContent=`${money(state.selected.coins)} ${id==='chosenCoins'?'Velvet Coins':'VC'}`);['chosenPrice','receiptPrice','receiptTotal','payAmount'].forEach(id=>document.querySelector('#'+id).textContent=`$${state.selected.price.toFixed(2)}${id==='receiptTotal'?' USD':''}`);document.querySelector('#checkout').classList.add('open');setStep(1)}
function setStep(n){document.querySelectorAll('.checkout-step').forEach(s=>s.classList.toggle('active',+s.dataset.step===n))}
function nextCheckout(){const active=document.querySelector('.checkout-step.active');setStep(+active.dataset.step+1)}
function pay(){setStep(4);setTimeout(()=>{state.balance+=state.selected.coins;updateBalance();document.querySelector('#successBalance').textContent=`${money(state.balance)} VC`;setStep(5)},2100)}
function closeCheckout(){document.querySelector('#checkout').classList.remove('open')}
function unlock(cost){if(state.balance<cost){toast('No tienes suficientes Velvet Coins.');showView('wallet');return}state.balance-=cost;updateBalance();toast(`Contenido desbloqueado · ${cost} VC usados`)}
document.querySelectorAll('.feed-tabs button,.profile-tabs button,.chips button').forEach(b=>b.addEventListener('click',()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));
updateBalance();
